import 'package:flutter_riverpod/flutter_riverpod.dart';

import 'bell_audio.dart'
    if (dart.library.js_interop) 'bell_web.dart'
    as platform;

/// The scoreboard's sounds, generated by `tool/make_bell.py` like a boxing ring's.
enum BellSound {
  /// One strike: the clock starts.
  start('bell_start.wav'),

  /// Three strikes: the match ends (points, time or disqualification).
  end('bell_end.wav'),

  /// Wooden clapper knocks: 10 seconds left.
  tenSeconds('ten_seconds.wav');

  const BellSound(this.file);

  final String file;
}

abstract interface class Bell {
  void play(BellSound sound);

  /// Called on every tap of the referee's screens: browsers only let a page make sound after the
  /// user touched it, so the first tap opens the audio for the bells that come later by themselves.
  void unlock();
}

/// A [Bell] that holds players or an audio context to release.
abstract interface class PlatformBell implements Bell {
  void dispose();
}

/// One for the whole app: the sounds are loaded once, before the first match.
final bellProvider = Provider<Bell>((ref) {
  final bell = platform.createBell();
  ref.onDispose(bell.dispose);
  return bell;
});
